tool_input.command:
Start-Sleep -Seconds 15
$paths=@("$env:LOCALAPPDATA\Programs\Ollama\ollama.exe","C:\Program Files\Ollama\ollama.exe")
$found=$false
foreach($x in $paths){ if(Test-Path $x){ "找到: $x"; $found=$true } }
if(-not $found){ "尚未落盘" }
Write-Output "=== OllamaSetup 进程还在? ==="
Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.ProcessName -match 'OllamaSetup|Ollama' } | Select-Object Id,ProcessName,@{n='Mem(MB)';e={[int]($_.WorkingSet/1MB)}}

$ollama="$env:LOCALAPPDATA\Programs\Ollama\ollama.exe"
& $ollama list 2>&1 | Select-Object -First 5
try{ $r=Invoke-RestMethod "http://127.0.0.1:11434/api/tags" -TimeoutSec 10; "模型: $(($r.models | ForEach-Object {$_.name+'('+[int]($_.size/1MB)+'MB)'}) -join ', ')" }catch{"err"}

$sp="C:\Program Files\Python310\lib\site-packages"
Write-Output "=== 工厂 create/build embedder 的 provider 分派 ==="
Get-ChildItem "$sp\openviking\models\embedder" -File | ForEach-Object { $m=Select-String -Path $_.FullName -Pattern 'provider ==|== "ollama"|"ollama"|build_embedder|def build|def create_embedder|provider.lower' -ErrorAction SilentlyContinue; if($m){ "--- $($_.Name) ---"; $m | ForEach-Object { "  L$($_.LineNumber): $($_.Line.Trim())" } } }
Write-Output "=== 配置层 account_config/binding 里 provider 映射 ==="
Get-ChildItem "$sp\openviking\config" -File | ForEach-Object { $m=Select-String -Path $_.FullName -Pattern 'ollama|litellm' -ErrorAction SilentlyContinue; if($m){ "--- $($_.Name) ---"; $m | ForEach-Object { "  L$($_.LineNumber): $($_.Line.Trim())" } } }

$sp="C:\Program Files\Python310\lib\site-packages"
Write-Output "=== 全包搜 create embedder / provider registry ==="
Get-ChildItem "$sp\openviking" -Recurse -File -Include "*.py" | ForEach-Object { $m=Select-String -Path $_.FullName -Pattern 'LiteLLMDenseEmbedder\(|provider_map|EMBEDDER_PROVIDERS|"ollama":|def .*embedder.*provider|def create_embedder|_build_embedder|embedder_provider' -ErrorAction SilentlyContinue; if($m){ "--- $($_.FullName.Replace($sp,'')) ---"; $m | Select-Object -First 5 | ForEach-Object { "  L$($_.LineNumber): $($_.Line.Trim())" } } }

$cfg="$env:USERPROFILE\.openviking\ov.conf"
Start-Process -FilePath "C:\Program Files\Python310\Scripts\openviking-server.exe" -ArgumentList "--config","`"$cfg`"" -WindowStyle Hidden -RedirectStandardOutput "$env:USERPROFILE\.openviking\state\server.out.log" -RedirectStandardError "$env:USERPROFILE\.openviking\state\server.err.log"
Write-Output "已启动 openviking-server，等待就绪..."
$ok=$false
for($i=1;$i -le 30 -and -not $ok;$i++){
  Start-Sleep -Seconds 3
  try{ $r=Invoke-RestMethod "http://127.0.0.1:1933/health" -TimeoutSec 5; "health OK (${i}x3s): $($r|ConvertTo-Json -Compress)"; $ok=$true }catch{}
}
if(-not $ok){ Write-Output "未就绪，查日志:"; Get-Content "$env:USERPROFILE\.openviking\state\server.err.log" -ErrorAction SilentlyContinue -Tail 20 }

Write-Output "=== server 进程 ==="
Get-Process -Name "openviking-server" -ErrorAction SilentlyContinue | Select-Object Id,ProcessName,StartTime
Write-Output "=== API: 检查 ov 命令连通 ==="
# ov CLI 需要 ovcli.conf 指向 server；先用 REST 探探
try{
  $r = Invoke-RestMethod "http://127.0.0.1:1933/api/v1/sessions" -TimeoutSec 10 -ErrorAction Stop
  "sessions: $($r|ConvertTo-Json -Compress)"
}catch{ "sessions API: $($_.Exception.Message.Split([char]10)[0])" }
Write-Output "=== 试 health 和根路径 ==="
try{ $r2=Invoke-WebRequest "http://127.0.0.1:1933/" -UseBasicParsing -TimeoutSec 8; "root status=$($r2.StatusCode)" }catch{ "root: $($_.Exception.Message.Split([char]10)[0])" }

$sid="dsh-session-9548209d-a5ab-4106-aa57-a11413f55d89"
Write-Output "=== 该 session 下的内容 ==="
try{
  $r = Invoke-RestMethod "http://127.0.0.1:1933/api/v1/sessions/$sid" -TimeoutSec 10 -ErrorAction Stop
  $r | ConvertTo-Json -Depth 5 -Compress | Select-Object -First 1
}catch{ "detail: $($_.Exception.Message.Split([char]10)[0])" }
Write-Output "=== 列所有 session 数量 ==="
$r2 = Invoke-RestMethod "http://127.0.0.1:1933/api/v1/sessions" -TimeoutSec 10
"session 数: $($r2.result.Count)"

Write-Output "=== DSH 插件配置：搜 openviking 在 profile 配置里 ==="
Get-ChildItem "$env:USERPROFILE\.dsh\profiles\web" -File -Include "*.yml","*.yaml","*.json" -Recurse -ErrorAction SilentlyContinue | Where-Object { $_.Name -notmatch '\.bak|lock|node_modules' } | ForEach-Object {
  $m=Select-String -Path $_.FullName -Pattern "openviking|ov-memory|1933" -ErrorAction SilentlyContinue
  if($m){ "--- $($_.FullName.Replace($env:USERPROFILE,'~')) ---"; $m | Select-Object -First 10 | ForEach-Object { "  L$($_.LineNumber): $($_.Line.Trim())" } }
}
Write-Output "=== 已安装的插件包 ==="
Get-ChildItem "$env:USERPROFILE\.dsh\profiles\web\node_modules\@yadsh" -ErrorAction SilentlyContinue | Select-Object Name
Get-ChildItem "$env:USERPROFILE\.dsh\profiles\web\node_modules\@openviking" -ErrorAction SilentlyContinue | Select-Object Name

Write-Output "=== Ollama 自启项(注册表 Run / 启动文件夹 / 计划任务) ==="
Get-ItemProperty "HKCU:\Software\Microsoft\Windows\CurrentVersion\Run" -ErrorAction SilentlyContinue | Get-Member -MemberType NoteProperty | Where-Object {$_.Name -match 'ollama'} | ForEach-Object { "  Run: $($_.Name)" }
Get-ChildItem "$env:APPDATA\Microsoft\Windows\Start Menu\Programs\Startup" -ErrorAction SilentlyContinue | ForEach-Object { "  Startup: $($_.Name)" }
schtasks /query /fo LIST 2>$null | Select-String -Pattern "Ollama" | Select-Object -First 3
Write-Output "=== 当前 openviking-server 是否注册了自启 ==="
schtasks /query /fo LIST 2>$null | Select-String -Pattern "openviking|OpenViking" | Select-Object -First 3
Get-ChildItem "$env:APPDATA\Microsoft\Windows\Start Menu\Programs\Startup" -ErrorAction SilentlyContinue | Where-Object {$_.Name -match 'openviking|ov'} | ForEach-Object { "  Startup: $($_.Name)" }

$sid="dsh-session-9548209d-a5ab-4106-aa57-a11413f55d89"
Write-Output "=== 找 commit API 路由 ==="
try{
  $r = Invoke-RestMethod "http://127.0.0.1:1933/openapi.json" -TimeoutSec 10 -ErrorAction Stop
  $paths = $r.paths.PSObject.Properties.Name | Where-Object { $_ -match 'commit|session' }
  $paths | Select-Object -First 20
}catch{ "openapi: $($_.Exception.Message.Split([char]10)[0])" }

$sid="dsh-session-9548209d-a5ab-4106-aa57-a11413f55d89"
Write-Output "=== 触发 commit ==="
try{
  $r = Invoke-RestMethod "http://127.0.0.1:1933/api/v1/sessions/$sid/commit" -Method Post -ContentType "application/json" -Body "{}" -TimeoutSec 120
  "commit 响应: " + ($r | ConvertTo-Json -Depth 4 -Compress)
}catch{ "commit FAIL: $($_.Exception.Message.Split([char]10)[0])" }

